import { TeamsConnectorError } from "./connector.js";
const VERDICT_CACHE_MAX = 2_000;
const HOME_TENANT_ROLES = new Set(["user", "member", "admin", "owner"]);
const VERDICT_TTL_MS = {
    member: 10 * 60_000,
    external: 2 * 60_000,
};
/** Tenant ids are GUIDs. Letter case is not part of the id. */
export function sameTeamsTenant(left, right) {
    return left !== undefined && right !== undefined && left.toLowerCase() === right.toLowerCase();
}
/** External unless Teams names the member a member or owner of the expected tenant. */
export function isExternalTeamsMember(member, tenantId) {
    return (member === undefined ||
        member.userRole === undefined ||
        !HOME_TENANT_ROLES.has(member.userRole) ||
        !sameTeamsTenant(member.tenantId, tenantId));
}
/**
 * Look a sender up once per team or conversation, because a member of
 * one team can be a guest in another. A membership is kept longer than
 * a refusal. A lookup that throws is unverified and is not kept, so the
 * next message asks again.
 */
export function createExternalSenderCheck(deps) {
    const now = deps.now ?? Date.now;
    const verdicts = new Map();
    return {
        async verdict({ serviceUrl, conversation, author, tenantId }) {
            const nowMs = now();
            const rosterId = conversation.teamId ?? conversation.id;
            const key = `${tenantId}\n${rosterId}\n${author.id}`;
            const cached = verdicts.get(key);
            if (cached !== undefined && cached.expiresAtMs > nowMs) {
                return cached.verdict;
            }
            if (cached !== undefined) {
                verdicts.delete(key);
            }
            let member;
            try {
                member = await deps.connector.member({
                    serviceUrl,
                    conversationId: rosterId,
                    memberId: author.id,
                });
            }
            catch (error) {
                deps.log(lookupFailure(author.id, error));
                return "unverified";
            }
            const verdict = isExternalTeamsMember(member, tenantId)
                ? "external"
                : "member";
            verdicts.set(key, { verdict, expiresAtMs: nowMs + VERDICT_TTL_MS[verdict] });
            if (verdicts.size > VERDICT_CACHE_MAX) {
                const oldest = verdicts.keys().next().value;
                if (oldest !== undefined) {
                    verdicts.delete(oldest);
                }
            }
            return verdict;
        },
    };
}
function lookupFailure(authorId, error) {
    if (error instanceof TeamsConnectorError) {
        return `warn could not look up Teams sender ${authorId}: HTTP ${error.status}, so it is refused`;
    }
    const message = error instanceof Error ? error.message : String(error);
    return `warn could not look up Teams sender ${authorId}: ${message}, so it is refused`;
}
